export function normalizeNigerianPhone(input) {
  if (typeof input !== "string") return null;

  let national = input.replace(/[\s().-]/g, "");

  if (!/^\+?\d+$/.test(national)) return null;

  if (national.startsWith("+")) {
    if (!national.startsWith("+234")) return null;
    national = national.slice(4);
  } else if (national.startsWith("00234")) {
    national = national.slice(5);
  } else if (national.startsWith("234")) {
    national = national.slice(3);
  }

  if (national.startsWith("00")) return null;
  if (national.startsWith("0")) {
    national = national.slice(1);
  }

  if (!/^[789][01]\d{8}$/.test(national)) return null;

  return `+234${national}`;
}

export function formatNigerianPhone(input) {
  const normalized = normalizeNigerianPhone(input);
  if (normalized === null) return null;

  const national = `0${normalized.slice(4)}`;
  return `${national.slice(0, 4)} ${national.slice(4, 7)} ${national.slice(7)}`;
}
